float CTCShop::GetCurrentBasicPrice(long def, long add) const
{
    CDefPointer<const CThingBaseDef> pdef;
    GetDefinitionManager().GetDef(ParentThing->GetDefGlobalIndex(), &pdef);
    CDefPointer<const CShopDef> ShopDef;
